
import sqlite3
import pandas as pd
import os

DATABASE_PATH = "database/loyaltyiq.db"


def create_database():

    print("\nLOYALTYIQ DATABASE SETUP")
    print("=" * 40)

    os.makedirs("database", exist_ok=True)

    # Connect to SQLite database
    connection = sqlite3.connect(DATABASE_PATH)

    print("Database connected successfully!")

    # CSV reports generated by reconciliation.py
    reports = {
        "customers": "data/customers.csv",
        "transactions": "data/transactions.csv",
        "points_earned": "data/points_earned.csv",
        "points_redeemed": "data/points_redeemed.csv",
        "points_expired": "data/points_expired.csv",
        "transaction_reconciliation": "reports/transaction_reconciliation.csv",
        "customer_balance_report": "reports/customer_balance_report.csv"
    }

    for table_name, file_path in reports.items():

        if os.path.exists(file_path):

            df = pd.read_csv(file_path)

            df.to_sql(
                table_name,
                connection,
                if_exists="replace",
                index=False
            )

            print(
                f"{table_name} table created: {len(df)} records"
            )

        else:
            print(f"File not found: {file_path}")

    connection.close()

    print("\nDatabase setup completed!")


if __name__ == "__main__":
    create_database()
